package com.coffeeshop.controller;
import com.coffeeshop.dto.TableManagementCommands;import com.coffeeshop.model.CustomerModels;import com.coffeeshop.model.TableManagementModels.*;import com.coffeeshop.service.*;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.concurrent.CompletableFuture;
public final class ReservationsController{
 private static final List<String> STATES=List.of("PENDING","CONFIRMED","SEATED","COMPLETED","CANCELLED","NO_SHOW");private final TableManagementService tablesService;private final CustomerService customersService;private List<CafeTable>tables=List.of();private List<CustomerModels.Option>customers=List.of();@FXML private TableView<Reservation>reservationTable;@FXML private TableColumn<Reservation,String>numberColumn,tableColumn,guestColumn,startColumn,partyColumn,statusColumn;@FXML private Label reservationMessage;@FXML private Button editReservationButton;
 public ReservationsController(TableManagementService t,CustomerService c){tablesService=Objects.requireNonNull(t);customersService=Objects.requireNonNull(c);}
 @FXML private void initialize(){numberColumn.setCellValueFactory(v->text(v.getValue().number()));tableColumn.setCellValueFactory(v->text(v.getValue().tableName()));guestColumn.setCellValueFactory(v->text(v.getValue().guestName()));startColumn.setCellValueFactory(v->text(v.getValue().startsAt().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"))));partyColumn.setCellValueFactory(v->text(""+v.getValue().partySize()));statusColumn.setCellValueFactory(v->text(v.getValue().status().replace('_',' ')));reservationTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->editReservationButton.setDisable(b==null));refresh();}
 @FXML private void refresh(){CompletableFuture.supplyAsync(()->new Data(tablesService.tables(),tablesService.reservations(),customersService.activeOptions())).whenComplete((d,e)->Platform.runLater(()->{if(e!=null){reservationMessage.setText("Unable to load reservations.");return;}tables=d.tables;customers=d.customers;reservationTable.getItems().setAll(d.reservations);reservationMessage.setText(d.reservations.isEmpty()?"No reservations are configured.":"");}));}
 @FXML private void addReservation(){edit(null);}@FXML private void editReservation(){Reservation r=reservationTable.getSelectionModel().getSelectedItem();if(r!=null)edit(r);}
 private void edit(Reservation r){List<CafeTable>available=tables.stream().filter(t->t.active()||r!=null&&t.id()==r.tableId()).toList();if(available.isEmpty()){reservationMessage.setText("Create and activate a cafe table first.");return;}Dialog<TableManagementCommands.SaveReservation>d=new Dialog<>();ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.setTitle(r==null?"Add reservation":"Edit reservation");d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);ComboBox<CafeTable>table=combo(available);table.setValue(r==null?available.getFirst():available.stream().filter(x->x.id()==r.tableId()).findFirst().orElse(available.getFirst()));ComboBox<CustomerModels.Option>customer=combo(customers);customer.setEditable(true);if(r!=null&&r.customerId()!=null)customer.setValue(customers.stream().filter(x->x.id()==r.customerId()).findFirst().orElse(null));TextField guest=new TextField(r==null?"":r.guestName()),phone=new TextField(r==null||r.phone()==null?"":r.phone()),email=new TextField(r==null||r.email()==null?"":r.email()),time=new TextField(r==null?"18:00":r.startsAt().toLocalTime().toString());DatePicker date=new DatePicker(r==null?LocalDate.now().plusDays(1):r.startsAt().toLocalDate());Spinner<Integer>party=new Spinner<>(1,999,r==null?2:r.partySize());ComboBox<String>status=combo(STATES);status.setValue(r==null?"PENDING":r.status());TextArea notes=new TextArea(r==null||r.notes()==null?"":r.notes());notes.setPrefRowCount(2);GridPane f=new GridPane();f.setHgap(12);f.setVgap(8);Control[]controls={table,guest,phone,email,customer,date,time,party,status,notes};String[]labels={"Table","Guest name","Phone","Email","Customer (optional)","Date","Time (HH:mm)","Party size","Status","Notes"};for(int i=0;i<labels.length;i++){f.add(new Label(labels[i]),0,i);controls[i].setMaxWidth(Double.MAX_VALUE);f.add(controls[i],1,i);}d.getDialogPane().setContent(f);d.getDialogPane().setPrefWidth(540);d.setResultConverter(b->{if(b!=save)return null;try{LocalTime at=LocalTime.parse(time.getText().trim());CustomerModels.Option selected=customer.getValue();return new TableManagementCommands.SaveReservation(r==null?null:r.id(),table.getValue().id(),selected==null?null:selected.id(),guest.getText(),phone.getText(),email.getText(),LocalDateTime.of(date.getValue(),at),party.getValue(),status.getValue(),notes.getText(),r==null?null:r.rowVersion());}catch(RuntimeException e){throw new IllegalArgumentException("Enter a valid date and time.");}});try{d.showAndWait().ifPresent(this::save);}catch(IllegalArgumentException e){reservationMessage.setText(e.getMessage());}}
 private void save(TableManagementCommands.SaveReservation q){CompletableFuture.supplyAsync(()->tablesService.saveReservation(q)).whenComplete((id,e)->Platform.runLater(()->{if(e==null){refresh();reservationMessage.setText("Reservation saved.");}else reservationMessage.setText(message(e));}));}private static <T>ComboBox<T>combo(Collection<T>items){ComboBox<T>x=new ComboBox<>();x.getItems().setAll(items);return x;}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to save the reservation.";}private record Data(List<CafeTable>tables,List<Reservation>reservations,List<CustomerModels.Option>customers){}
}
